pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address _baseToken) public {
        vm.assume(_baseToken != address(0));
        try c.initialize(
            _baseToken,
            address(0x1),
            100,
            100,
            0,
            100,
            bytes32(0),
            false,
            false
        ) {} catch { return; }
        assertTrue(c.baseToken() == _baseToken);
    }
}
